"""Get the elements of the file name we need

    Params:
        fname -- String: The file name
                c9_c8_c176_IC12_s4_l_t

    Returns:
        The image's component number, scan number, and hemisphere
        12, 4, L
    """
def get_name(fname: Any) -> object {
    if fname.endswith('.nii.gz') {
        fname = fname.replace('.nii.gz', '');
    }
    name_stuff = {};
    tmp = fname.split('_');
    elems = tmp[-4:-1];
    name_stuff['IC'] = elems[0][2:];
    name_stuff['Scan'] = elems[1][1:];
    name_stuff['Hemi'] = elems[2].upper();
    return name_stuff;
}

"""
    function that checks for the similarity between the words of
    two strings.

    :param x: first string
    :param y: second string

    :return: returns a float number which is the result of the
     division of the length of the intersection between the two strings'
     words by the length of their union.
     """
def similar(x: Any, y: Any) -> object {
    result = '';
    x_list = x.split();
    x_list = [word.lower() for word in x_list];
    x_list = `list(`set(x_list));
    y_list = y.split();
    y_list = [word.lower() for word in y_list];
    y_list = `list(`set(y_list));
    intersection = [
        word
        for word in x_list
        if (word in y_list)
    ];
    union = `list(`set(x_list).union(y_list));
    result = float((len(intersection) / len(union)));
    return result;
}

